FUNCTION UNDER TEST:
Name: add_numbers
Signature: int add_numbers(uint8_t *a, uint8_t *b, uint8_t N)
Description: /**
 * @brief Add two decimal digit arrays with carry propagation.
 *
 * Performs element-wise addition of two arrays representing decimal digits
 * (0-9) stored in little-endian order (least significant digit at index 0).
 * The result is accumulated in the second array, which must have extra
 * capacity to handle a final carry. The function propagates carries through
 * all digits and up to 10 additional positions if needed.
 *
 * @param a First addend array. Must contain N valid decimal digits (0-9).
 * @param b Second addend array and result storage. Must contain at least
 *          N+10 elements initialized with decimal digits (0-9) in the first
 *          N positions. Modified to contain the sum.
 * @param N Number of digits to add from the start of each array.
 *
 * @return Always returns 0. Errors are not signaled; invalid input may
 *         cause undefined behavior.
 *
 * @note The arrays represent numbers in little-endian decimal format.
 * @note The result array `b` must have capacity for N+10 elements to
 *       accommodate worst-case carry propagation.
 */
Dependencies: None

FUNCTION IMPLEMENTATION (REFERENCE ONLY - do NOT copy into test):
```c
// C program for the function called add_numbers
// Contains target function implementation and dependency signatures

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Target function implementation
int add_numbers(uint8_t *a, uint8_t *b, uint8_t N)
{
    int carry = 0;
    uint8_t *c = b; /* accumulate the result in the array 'b' */

    for (int i = 0; i < N; i++)
    {
        // printf("	%d + %d + %d ", a[i], b[i], carry);
        c[i] = carry + a[i] + b[i];  // NOLINT // This is a known false-positive
        if (c[i] > 9)                /* check for carry */
        {
            carry = 1;
            c[i] -= 10;
        }
        else
        {
            carry = 0;
        }
        // printf("= %d, %d
", carry, c[i]);
    }

    for (int i = N; i < N + 10; i++)
    {
        if (carry == 0)
        {
            break;
        }
        // printf("	0 + %d + %d ", b[i], carry);
        c[i] = carry + c[i];
        if (c[i] > 9)
        {
            carry = 1;
            c[i] -= 10;
        }
        else
        {
            carry = 0;
        }
        // printf("= %d, %d
", carry, c[i]);
    }
    return 0;
}

